import { ChangeDetectionStrategy, Component, ElementRef, inject, input } from '@angular/core';

@Component({
  selector: 'aevko-input-group',
  standalone: true,
  template: '<ng-content />',
  styleUrl: './input-group.component.css',
  changeDetection: ChangeDetectionStrategy.OnPush,
  host: { role: 'group', 'data-slot': 'input-group' },
})
export class AevkoInputGroup {}

@Component({
  selector: 'aevko-input-group-addon',
  standalone: true,
  template: '<ng-content />',
  styleUrl: './input-group-addon.component.css',
  changeDetection: ChangeDetectionStrategy.OnPush,
  host: {
    role: 'group',
    'data-slot': 'input-group-addon',
    '[attr.data-align]': 'align()',
    '(click)': 'focusControl($event)',
  },
})
export class AevkoInputGroupAddon {
  private readonly element = inject<ElementRef<HTMLElement>>(ElementRef);
  readonly align = input<'inline-start' | 'inline-end' | 'block-start' | 'block-end'>(
    'inline-start',
  );

  protected focusControl(event: MouseEvent): void {
    if ((event.target as HTMLElement).closest('button, a')) {
      return;
    }
    this.element.nativeElement.parentElement
      ?.querySelector<HTMLElement>('input, textarea, select')
      ?.focus();
  }
}

@Component({
  selector: 'input[aevkoInputGroupControl], textarea[aevkoInputGroupControl]',
  standalone: true,
  template: '',
  styleUrl: './input-group-control.component.css',
  changeDetection: ChangeDetectionStrategy.OnPush,
  host: { 'data-slot': 'input-group-control' },
})
export class AevkoInputGroupControl {}

@Component({
  selector: 'button[aevkoInputGroupButton]',
  standalone: true,
  template: '<ng-content />',
  styleUrl: './input-group-button.component.css',
  changeDetection: ChangeDetectionStrategy.OnPush,
  host: {
    type: 'button',
    'data-slot': 'input-group-button',
    '[attr.data-size]': 'size()',
    '[attr.data-variant]': 'variant()',
  },
})
export class AevkoInputGroupButton {
  readonly size = input<'xs' | 'sm' | 'icon-xs' | 'icon-sm'>('xs');
  readonly variant = input<'ghost' | 'outline'>('ghost');
}

:host {
  align-items: stretch;
  background: var(--aevko-background, #fff);
  border: 1px solid var(--aevko-border-strong, #a1a1aa);
  border-radius: var(--aevko-radius, 0);
  display: flex;
  flex-wrap: wrap;
  min-height: 2.75rem;
  width: 100%;
}
:host:focus-within {
  border-color: var(--aevko-focus, #a1a1aa);
  outline: 2px solid var(--aevko-focus, #a1a1aa);
  outline-offset: 1px;
}
:host:has([aria-invalid='true']) {
  border-color: var(--aevko-danger, #3f3f3f);
}

:host {
  align-items: center;
  color: var(--aevko-muted, #71717a);
  display: inline-flex;
  gap: 0.375rem;
  padding-inline: 0.75rem;
}
:host([data-align='inline-start']) {
  order: -1;
}
:host([data-align='block-start']),
:host([data-align='block-end']) {
  flex-basis: 100%;
  min-height: 2.25rem;
}
:host([data-align='block-start']) {
  border-bottom: 1px solid var(--aevko-border, #e4e4e7);
  order: -1;
}
:host([data-align='block-end']) {
  border-top: 1px solid var(--aevko-border, #e4e4e7);
}

:host {
  appearance: none;
  background: transparent;
  border: 0;
  color: var(--aevko-foreground, #09090b);
  flex: 1 1 10rem;
  font: 500 1rem/1.4 var(--aevko-font-sans, sans-serif);
  min-height: 2.625rem;
  min-width: 0;
  outline: 0;
  padding: 0.625rem 0.75rem;
  resize: vertical;
}
:host::placeholder {
  color: var(--aevko-muted, #71717a);
}
:host:disabled {
  cursor: not-allowed;
  opacity: 0.5;
}

:host {
  align-self: center;
  background: transparent;
  border: 0;
  color: inherit;
  cursor: pointer;
  font: 500 0.8125rem/1 var(--aevko-font-sans, sans-serif);
  min-height: 2rem;
  padding-inline: 0.625rem;
}
:host([data-size='sm']) {
  min-height: 2.25rem;
  padding-inline: 0.75rem;
}
:host([data-size='icon-xs']),
:host([data-size='icon-sm']) {
  aspect-ratio: 1;
  padding: 0;
}
:host([data-size='icon-xs']) {
  min-height: 1.75rem;
}
:host([data-size='icon-sm']) {
  min-height: 2.25rem;
}
:host([data-variant='outline']) {
  border: 1px solid var(--aevko-border-strong, #a1a1aa);
}
:host(:hover:not(:disabled)) {
  background: var(--aevko-surface, #f4f4f5);
}
:host:focus-visible {
  outline: 2px solid var(--aevko-focus, #a1a1aa);
  outline-offset: -2px;
}
:host:disabled {
  cursor: not-allowed;
  opacity: 0.5;
}
